!function(){"use strict";const e={waterfall:{badge:"Step 1: The Legendary Cascade",title:"The Sacred Ribbon of Budhabalanga",desc:"Named 'Barehipani' after the local Mayurbhanj term 'Barahi' (twisted rope), the waterfall resembles a colossal braided silver rope descending over dark Meghasani cliff faces into a secluded, cloud-shrouded jungle valley.",img:"https://images.unsplash.com/photo-1542385151-efd9000785a0?auto=format&fit=crop&q=80&w=800",caption:"Full-scale view of Barehipani's 399m vertical cascade over dark Precambrian basalt",meta:[{label:"River",val:"Budhabalanga River"},{label:"Type",val:"Two-tiered plunge waterfall"},{label:"Rank",val:"2nd Tallest in India (399m / 1,309 ft)"}]},height:{badge:"Step 2: Monumental Vertical Drop",title:"399-Meter Dual Tier Descent",desc:"The cascade splits cleanly across two sheer cliff drops: a massive upper freefall of 260 meters followed by a 139-meter lower chasm plunge, ranking it higher than Goa's Dudhsagar and Karnataka's Jog Falls.",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",caption:"Dual tiered plunge basin view showing upper 260m drop and lower 139m spray gorge",meta:[{label:"Total Height",val:"399 meters (1,309 feet)"},{label:"Upper Tier",val:"260 meters direct freefall"},{label:"Lower Tier",val:"139 meters plunge chasm"}]},landscape:{badge:"Step 3: Similipal Biosphere Reserve",title:"Ancient Sal Canopies & Tiger Habitat",desc:"Surrounding the falls is the 2,750 km² Similipal UNESCO Biosphere Reserve, rich in dense Shorea robusta (Sal) forests, 94 species of wild orchids, and the world's only wild melanistic Royal Bengal tigers.",img:"https://images.unsplash.com/photo-1575550959106-5a7defe28b56?auto=format&fit=crop&q=80&w=800",caption:"Vast pristine Sal canopy of Similipal Tiger Reserve surrounding the waterfall gorge",meta:[{label:"Protected Area",val:"Similipal Tiger Reserve (UNESCO)"},{label:"Key Wildlife",val:"Melanistic tigers, Asian elephants, Gaurs"},{label:"Flora",val:"94 Orchid species, moist deciduous Sal"}]},season:{badge:"Step 4: Seasonal Transformation",title:"Winter Splendor & Monsoon Fury",desc:"November to February offers peak viewing with crisp weather and emerald waters. Monsoon brings colossal volume but park tracks close for public safety. Summer offers golden canopy walks.",img:"https://images.unsplash.com/photo-1596773229676-e13d98fb8a76?auto=format&fit=crop&q=80&w=800",caption:"Winter morning view of misty Budhabalanga river canyon at peak tourist opening",meta:[{label:"Best Visiting Season",val:"November to February"},{label:"Park Status",val:"Open Nov 1 – June 15 (Closed in Monsoon)"},{label:"Temperature",val:"8°C – 24°C in winter"}]},location:{badge:"Step 5: Geographic Setting",title:"Heart of Mayurbhanj, Northern Odisha",desc:"Situated inside the core zone of Similipal in Mayurbhanj district, 120 km from Baripada and accessible via Jashipur and Pithabata entry gates with authorized forest safaris.",img:"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&q=80&w=800",caption:"Meghasani mountain range framing the remote core sanctuary of Similipal",meta:[{label:"District",val:"Mayurbhanj, Odisha"},{label:"Entry Gates",val:"Jashipur (NW) & Pithabata (NE)"},{label:"Nearest Hub",val:"Baripada (120 km) / Balasore (145 km)"}]}},t={winter:{title:"Winter Peak (November to February) — Best Season",desc:"The park reopens on November 1st after the monsoons. Temperatures range from a crisp 8°C to 22°C. The Budhabalanga River roars with fresh post-monsoon volume, mist shimmers over the canyon, and safari tracks are completely accessible.",flow:"Flow: Massive Silver Cascade & Dense Mist",access:"Park Access: Open (Permits required at Jashipur / Pithabata)",highlight:"Highlights: Wildlife safaris, orchid flowering, birdwatching"},summer:{title:"Spring & Summer (March to June)",desc:"Flow tapers into a slender silver stream. The deciduous sal forest sheds leaves, vastly improving wildlife visibility for spotting tigers, elephants, and barking deer around watering holes.",flow:"Flow: Moderate Stream & Crystal Pool",access:"Park Access: Open until mid-June",highlight:"Highlights: Prime wildlife photography around riverbeds"},monsoon:{title:"Monsoon Deluge (July to October) — Sanctuary Closed",desc:"Heavy tropical downpours flood the Budhabalanga River into an impassable torrent. The core biosphere reserve is strictly closed to tourists for wildlife breeding and safety reasons.",flow:"Flow: Thunderous Reddish Torrential Flood",access:"Park Access: Strictly CLOSED for conservation",highlight:"Highlights: Nature regeneration & groundwater replenishment"}},a={barehipani:{title:"Barehipani Falls Overlook Pavilion",sub:"Head-On Viewing Terrace (399m Drop)",desc:"Constructed on the opposite rim of the canyon, the forest observation terrace offers a panoramic, full-length vantage point of both upper and lower cascading tiers.",dist:"Core Zone Overlook",vehicle:"Authorized 4x4 Gypsy with eco-guide",rail:"Baripada (120 km) / Balasore (145 km)"},joranda:{title:"Joranda Falls (181m)",sub:"Single-Drop Companion Cascade",desc:"Located just 20 km from Barehipani, Joranda falls perpendicularly off a single 181m cliff, making it an essential pair on the Similipal circuit.",dist:"20 km from Barehipani",vehicle:"4x4 Safari Track",rail:"Baripada (100 km)"},jashipur:{title:"Jashipur Entry Gate & Booking Counter",sub:"North-Western Park Gateway",desc:"The primary entry gate on NH-49 for tourists arriving from Kolkata, Ranchi, or Rourkela. Forest permits, entry passes, and registered Gypsy safaris start here.",dist:"60 km to Barehipani",vehicle:"Highway access on NH-49",rail:"Tatanagar (105 km)"},pithabata:{title:"Pithabata Entry Gate & Information Centre",sub:"North-Eastern Park Gateway near Baripada",desc:"The eastern entry point situated 22 km from Baripada town, providing entry passes and eco-guides for visitors exploring the eastern Similipal range.",dist:"120 km to Barehipani",vehicle:"Paved road from Baripada",rail:"Baripada (22 km) / Balasore (85 km)"},meghasani:{title:"Meghasani Peak (1,165 m)",sub:"Seat of Clouds & Highest Similipal Summit",desc:"The highest mountain summit in Mayurbhanj district ('Meghasani' = Seat of Clouds), functioning as the primary cloud-catcher that feeds the Budhabalanga and Khairi rivers.",dist:"Summit overlook ridge",vehicle:"Trek route from core stations",rail:"Baripada (130 km)"}};document.addEventListener("DOMContentLoaded",function(){const i=document.querySelectorAll(".step-btn"),o=document.getElementById("j-step-badge"),r=document.getElementById("j-title"),n=document.getElementById("j-desc"),s=document.getElementById("j-meta"),l=document.getElementById("j-img"),c=document.getElementById("j-caption"),d=document.querySelectorAll(".season-btn"),m=document.getElementById("s-card-title"),h=document.getElementById("s-card-desc"),u=document.getElementById("sp-flow"),p=document.getElementById("sp-access"),g=document.getElementById("sp-highlight"),f=document.querySelectorAll(".similipal-pin"),b=document.getElementById("loc-title"),v=document.getElementById("loc-sub"),y=document.getElementById("loc-body"),w=document.getElementById("loc-dist"),k=document.getElementById("loc-vehicle"),B=document.getElementById("loc-rail"),S=document.getElementById("theme-toggle");S&&S.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark")}),i.forEach(function(t){t.addEventListener("click",function(){i.forEach(e=>e.classList.remove("active")),t.classList.add("active");const a=t.getAttribute("data-step"),d=e[a];d&&(o&&(o.textContent=d.badge),r&&(r.textContent=d.title),n&&(n.textContent=d.desc),l&&(l.src=d.img,l.alt=d.caption),c&&(c.textContent=d.caption),s&&(s.innerHTML=d.meta.map(e=>`<div><strong>${e.label}:</strong> <span>${e.val}</span></div>`).join("")))})}),d.forEach(function(e){e.addEventListener("click",function(){d.forEach(e=>e.classList.remove("active")),e.classList.add("active");const a=e.getAttribute("data-season"),i=t[a];i&&(m&&(m.textContent=i.title),h&&(h.textContent=i.desc),u&&(u.textContent=i.flow),p&&(p.textContent=i.access),g&&(g.textContent=i.highlight))})}),f.forEach(function(e){e.addEventListener("click",function(){const t=e.getAttribute("data-spot"),i=a[t];i&&(b&&(b.textContent=i.title),v&&(v.textContent=i.sub),y&&(y.innerHTML=`<p>${i.desc}</p>`),w&&(w.textContent=i.dist),k&&(k.textContent=i.vehicle),B&&(B.textContent=i.rail))}),e.addEventListener("keydown",function(t){"Enter"!==t.key&&" "!==t.key||(t.preventDefault(),e.click())})});const E=document.getElementById("menu-toggle"),C=document.getElementById("nav-menu");E&&C&&E.addEventListener("click",()=>C.classList.toggle("active"))})}();